

const CURRENT_DATE_STR = (() => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; })();
const STORAGE_KEY_INVENTORY = 'ASSENT_WMS_INVENTORY_DATA_V1';
const STORAGE_KEY_TXN = 'ASSENT_WMS_TRANSACTIONS_V1';
const STORAGE_KEY_RECEIPTS = 'ASSENT_WMS_RECEIPTS_V1';
const STORAGE_KEY_DN = 'ASSENT_WMS_DELIVERY_NOTES_V1';

const DRR_TEMPLATE_B64 = "";

// Builds the DRR workbook by filling the embedded template's XML directly (no ExcelJS needed).
async function buildDrrXlsx(JSZipLib, templateB64, lines, opt) {
  const zip = await JSZipLib.loadAsync(templateB64, { base64: true });
  const PER = 15, BLOCK = 33;
  const pages = Math.max(1, Math.ceil(lines.length / PER));
  const esc = (v) => String(v == null ? '' : v).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const colNum = (L) => L.split('').reduce((n, ch) => n * 26 + ch.charCodeAt(0) - 64, 0);
  const colLet = (n) => { let s = ''; while (n > 0) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); } return s; };

  let sheet = await zip.file('xl/worksheets/sheet1.xml').async('string');
  const sd0 = sheet.indexOf('<sheetData>'), sd1 = sheet.indexOf('</sheetData>');
  const head = sheet.slice(0, sd0), tail = sheet.slice(sd1 + '</sheetData>'.length);
  const rowsXml = sheet.slice(sd0 + '<sheetData>'.length, sd1);

  const tpl = {};
  const rowRe = /<row r="(\d+)"([^>]*?)(?:\/>|>([\s\S]*?)<\/row>)/g;
  let m;
  while ((m = rowRe.exec(rowsXml))) {
    const cells = {}, order = [];
    const cellRe = /<c r="([A-Z]+)\d+"([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/g;
    let c;
    while ((c = cellRe.exec(m[3] || ''))) {
      cells[c[1]] = { attrs: c[2], inner: c[3], style: (c[2].match(/ s="(\d+)"/) || [])[1] };
      order.push(c[1]);
    }
    tpl[+m[1]] = { attrs: m[2], cells, order };
  }
  const styleOf = (r, col) => (tpl[r] && tpl[r].cells[col] && tpl[r].cells[col].style) || (tpl[7].cells[col] && tpl[7].cells[col].style);

  const [y, mo, d] = opt.dateISO.split('-').map(Number);
  const serial = Math.round(Date.UTC(y, mo - 1, d) / 86400000) + 25569;
  const DATA_COLS = { B: 'no', C: 'description', D: 'qty', E: 'grade', F: 'job', G: 'jobCode', H: 'supplier', I: 'po', J: 'doNo', K: 'heat', L: 'lot' };

  const cellXml = (ref, style, spec) => {
    const s = style ? ` s="${style}"` : '';
    if (spec.f) return `<c r="${ref}"${s}><f>${spec.f}</f><v>${spec.v}</v></c>`;
    if (spec.n !== undefined) return `<c r="${ref}"${s}><v>${spec.n}</v></c>`;
    return `<c r="${ref}"${s} t="inlineStr"><is><t xml:space="preserve">${esc(spec.t)}</t></is></c>`;
  };

  let out = '';
  for (let p = 0; p < pages; p++) {
    const off = BLOCK * p;
    const chunk = lines.slice(p * PER, (p + 1) * PER);
    const total = chunk.reduce((s, l) => s + (Number(l.qty) || 0), 0);
    for (let r = 1; r <= BLOCK; r++) {
      const t = tpl[r]; if (!t) continue;
      const nr = r + off;
      const ov = {};
      if (r === 3) ov.L = { t: opt.drrText };
      if (r === 5) ov.C = { n: serial };
      if (r === 32) ov.L = { t: `PAGE ${p + 1} OF ${pages}` };
      if (r === 29) ov.D = { f: `SUM(D${7 + off}:D${28 + off})`, v: total };
      let attrs = t.attrs.replace(/ spans="[^"]*"/, '');
      if (r >= 7 && r <= 21 && r - 7 < chunk.length) {
        const ln = chunk[r - 7], idx = p * PER + (r - 7) + 1;
        Object.keys(DATA_COLS).forEach((col) => {
          const k = DATA_COLS[col];
          if (k === 'no') ov[col] = { n: idx };
          else if (k === 'qty') ov[col] = { n: Number(ln.qty) || 0 };
          else ov[col] = { t: ln[k] };
        });
        ov.N = { n: serial };
        ov.O = { t: opt.drrText.replace(/^DRR/, '') };
      }
      if (r >= 7 && r <= 21) attrs = attrs.replace(/ ht="[\d.]+"/, ' ht="200"');
      const cols = Array.from(new Set([...t.order, ...Object.keys(ov)])).sort((a, b) => colNum(a) - colNum(b));
      let cx = '';
      cols.forEach((col) => {
        const ref = col + nr;
        if (ov[col]) {
          const forceStyle = (r >= 7 && r <= 21) ? styleOf(7, col) : styleOf(r, col);
          cx += cellXml(ref, forceStyle, ov[col]);
        } else {
          const c = t.cells[col];
          cx += c.inner === undefined ? `<c r="${ref}"${c.attrs}/>` : `<c r="${ref}"${c.attrs}>${c.inner}</c>`;
        }
      });
      out += cols.length ? `<row r="${nr}"${attrs}>${cx}</row>` : `<row r="${nr}"${attrs}/>`;
    }
  }

  let newHead = head.replace(/<dimension ref="([A-Z]+)(\d+):([A-Z]+)(\d+)"\/>/, (a, c1, r1, c2) => `<dimension ref="${c1}${r1}:${c2}${BLOCK * pages}"/>`);
  let newTail = tail;
  // merged cells repeat on every page
  const mm = newTail.match(/<mergeCells count="\d+">([\s\S]*?)<\/mergeCells>/);
  if (mm) {
    const refs = [...mm[1].matchAll(/<mergeCell ref="([A-Z]+)(\d+):([A-Z]+)(\d+)"\/>/g)];
    let all = '';
    for (let p = 0; p < pages; p++) refs.forEach((x) => { all += `<mergeCell ref="${x[1]}${+x[2] + BLOCK * p}:${x[3]}${+x[4] + BLOCK * p}"/>`; });
    newTail = newTail.replace(mm[0], `<mergeCells count="${refs.length * pages}">${all}</mergeCells>`);
  }
  if (pages > 1) {
    let brks = '';
    for (let p = 1; p < pages; p++) brks += `<brk id="${BLOCK * p}" max="16383" man="1"/>`;
    newTail = newTail.replace('<drawing', `<rowBreaks count="${pages - 1}" manualBreakCount="${pages - 1}">${brks}</rowBreaks><drawing`);
  }
  zip.file('xl/worksheets/sheet1.xml', newHead + '<sheetData>' + out + '</sheetData>' + newTail);

  // logo repeated on every page
  const dFile = zip.file('xl/drawings/drawing1.xml');
  if (dFile && pages > 1) {
    let dx = await dFile.async('string');
    const am = dx.match(/<(?:xdr:)?twoCellAnchor[^>]*>[\s\S]*?<\/(?:xdr:)?twoCellAnchor>/) || dx.match(/<(?:xdr:)?oneCellAnchor[^>]*>[\s\S]*?<\/(?:xdr:)?oneCellAnchor>/);
    if (am) {
      let extra = '';
      for (let p = 1; p < pages; p++) {
        extra += am[0].replace(/<((?:xdr:)?row)>(\d+)<\/((?:xdr:)?row)>/g, (a, o, n, c) => `<${o}>${+n + BLOCK * p}</${c}>`).replace(/<((?:xdr:)?cNvPr) id="\d+" name="[^"]*"/, (a, tg) => `<${tg} id="${100 + p}" name="Logo ${p + 1}"`);
      }
      dx = dx.replace(/<\/(xdr:)?wsDr>/, (a, px) => extra + a);
      zip.file('xl/drawings/drawing1.xml', dx);
    }
  }
  let wbx = await zip.file('xl/workbook.xml').async('string');
  wbx = wbx.replace(/(Print_Area"[^>]*>[^<]*\$L\$)33/, `$1${BLOCK * pages}`);
  zip.file('xl/workbook.xml', wbx);
  return zip.generateAsync({ type: 'uint8array', compression: 'DEFLATE' });
}

// ===================== Receiving verification engine (pure functions) =====================
const RV = (() => {
  const clean = (v) => (v == null ? '' : String(v).trim());
  const num = (v) => { const n = parseFloat(String(v == null ? '' : v).replace(/,/g, '')); return isNaN(n) ? 0 : n; };
  const alnum = (s) => clean(s).toUpperCase().replace(/[^A-Z0-9]/g, '');
  const uniq = (a) => Array.from(new Set(a.filter(Boolean)));
  let _seq = 0;
  const nid = (p) => p + (++_seq) + '-' + Math.floor(Math.random() * 1e4);

  // product families
  const productsOf = (text) => {
    const t = ' ' + clean(text).toUpperCase() + ' ';
    const bolt = /BOLT|SCREW|STUD|ANCHOR|\bROD\b/.test(t), nut = /\bNUT\b|\bNUTS\b/.test(t), washer = /WASHER/.test(t);
    if (/\bBNW\b|\(SET\)|\bSET\b/.test(t) || (bolt && (nut || washer))) {
      const ty = ['BOLT']; if (nut || /\bBNW\b/.test(t)) ty.push('NUT'); if (washer || /\bBNW\b/.test(t)) ty.push('WASHER');
      return ty;
    }
    if (nut) return ['NUT'];
    if (washer) return ['WASHER'];
    return ['BOLT'];
  };
  const mtcProduct = (p, desc) => {
    const t = clean(p).toUpperCase() + ' ' + clean(desc).toUpperCase();
    if (/WASHER/.test(t)) return 'WASHER';
    if (/\bNUT/.test(t)) return 'NUT';
    return 'BOLT';
  };
  // size tokens: [{d:'M16', l:'65'}] or [{d:'M20', l:''}]
  const sizeTokens = (text) => {
    const t = clean(text).toUpperCase().replace(/[×*]/g, 'X').replace(/\s+/g, '');
    const out = []; let m; const re = /M(\d{1,3})(?:X(\d{1,4})(?:\/(\d{1,4}))?)?/g;
    while ((m = re.exec(t))) out.push({ d: 'M' + m[1], l: m[2] || '' });
    // lengths in parentheses e.g. M16X60(65)
    const pm = t.match(/M\d+X\d+\((\d+)\)/); if (pm) { const d = (t.match(/M\d+/) || [''])[0]; out.push({ d, l: pm[1] }); }
    return out;
  };
  const sizeKey = (text) => { const k = sizeTokens(text); return k.length ? k[k.length - 1].d + (k[k.length - 1].l ? 'X' + k[k.length - 1].l : '') : alnum(text); };
  const diamOf = (text) => (sizeTokens(text)[0] || {}).d || '';
  const sizeMatches = (type, a, b) => {
    const A = sizeTokens(a), B = sizeTokens(b);
    if (!A.length || !B.length) return false;
    if (type === 'BOLT') return A.some((x) => B.some((y) => x.d === y.d && ((x.l && y.l && x.l === y.l) || (!x.l && !y.l) )));
    return A.some((x) => B.some((y) => x.d === y.d));
  };
  const gradeTokens = (text) => uniq((clean(text).toUpperCase().match(/\b[AF]\d{3,4}M?\b/g) || []).map((g) => g.replace(/M$/, '')));
  const gradeOf = (text) => (clean(text).toUpperCase().match(/\b[AF]\d{3,4}M?\b/g) || []).filter((g, i, a) => a.indexOf(g) === i).join('/');

  // ---- MTC auto link for one packing/delivery line ----
  const autoLink = (line, mtc) => {
    const types = productsOf(line.item + ' ' + line.size);
    const ids = [];
    types.forEach((t) => {
      const hits = mtc.filter((m) => m.product === t && sizeMatches(t, m.size, line.size || line.item));
      hits.forEach((h) => ids.push(h.id));
    });
    return ids;
  };
  const deriveHeatLot = (line, mtc) => {
    const rows = (line.mtcIds || []).map((id) => mtc.find((m) => m.id === id)).filter(Boolean);
    const order = { BOLT: 0, NUT: 1, WASHER: 2 };
    rows.sort((a, b) => (order[a.product] ?? 3) - (order[b.product] ?? 3));
    return {
      heatNo: uniq(rows.map((r) => clean(r.heatNo))).join(', '),
      lotNo: uniq(rows.map((r) => clean(r.lotNo))).join(', '),
      marking: uniq(rows.map((r) => clean(r.marking))).join(' / ')
    };
  };

  // ---- turn raw per-page AI results into a review object ----
  const buildReview = (results, pages, todayISO) => {
    const of = (t) => results.filter((r) => r.docType === t);
    const hdrOf = (k) => clean([...of('PACKING_LIST'), ...of('DELIVERY_NOTE'), ...results].map((r) => clean(r[k])).find(Boolean));
    const projRaw = clean(results.map((r) => clean(r.project)).find((p) => /^PR\s*-?\s*\d+/i.test(p)));
    const project = projRaw ? projRaw.toUpperCase().replace(/^PR\s*-?\s*/, 'PR-').replace(/\s+/g, '') : '';
    const stamp = clean(results.map((r) => clean(r.receivedDate)).find((d) => /^\d{4}-\d{2}-\d{2}$/.test(d)));

    const dedupe = (type, rowsKey) => {
      const seen = new Set(); const out = [];
      of(type).forEach((p) => {
        const rows = Array.isArray(p[rowsKey]) ? p[rowsKey] : [];
        const sig = JSON.stringify(rows.map((l) => [clean(l.item || l.product), clean(l.size), clean(l.totalQty), clean(l.cartons), clean(l.heatNo), clean(l.lotNo)]));
        if (!rows.length) return;
        if (seen.has(sig)) { p._dup = true; return; }
        seen.add(sig); rows.forEach((l) => out.push({ row: l, page: p._page }));
      });
      return out;
    };
    const mtc = [];
    const mseen = new Set();
    of('MTC').forEach((p) => (Array.isArray(p.mtcRows) ? p.mtcRows : []).forEach((m) => {
      const row = {
        id: nid('m'), product: mtcProduct(m.product, p.description), size: clean(m.size), grade: clean(m.grade) || clean(m.standard) || clean(p.standard),
        marking: clean(m.marking), heatNo: clean(m.heatNo), lotNo: clean(m.lotNo), qty: num(m.qtyPcs != null ? m.qtyPcs : m.qty), certNo: clean(p.certNo), poNo: clean(p.poNo), srcPage: p._page, unclear: Array.isArray(m.unclear) ? m.unclear : []
      };
      const k = [row.product, alnum(row.size), alnum(row.heatNo), alnum(row.lotNo)].join('|');
      if ((row.heatNo || row.lotNo || row.marking) && !mseen.has(k)) { mseen.add(k); mtc.push(row); }
    }));

    const dn = dedupe('DELIVERY_NOTE', 'lines').map(({ row: l, page }) => ({ id: nid('d'), item: clean(l.item), size: clean(l.size), grade: clean(l.grade) || gradeOf(l.item), uom: clean(l.uom) || 'PCS', qty: num(l.totalQty), weightKg: num(l.grossWeightKg), srcPage: page }));
    let pl = dedupe('PACKING_LIST', 'lines');
    let lastPallet = '1';
    pl = pl.map(({ row: l, page }) => {
      const hasPallet = !!clean(l.palletNo);
      lastPallet = clean(l.palletNo) || lastPallet;
      return { id: nid('p'), pallet: lastPallet, palletGuessed: !hasPallet, item: clean(l.item), size: clean(l.size), grade: clean(l.grade) || gradeOf(l.item), uom: clean(l.uom) || 'PCS', cartons: num(l.cartons), qtyPerCtn: num(l.qtyPerCarton), totalQty: num(l.totalQty), weightKg: num(l.grossWeightKg), srcPage: page, mtcIds: [], heatNo: '', lotNo: '', marking: '', unclear: Array.isArray(l.unclear) ? l.unclear : [] };
    });
    let plFromDn = false;
    if (!pl.length && dn.length) {
      plFromDn = true;
      pl = dn.map((d) => ({ id: nid('p'), pallet: '1', palletGuessed: true, item: d.item, size: d.size, grade: d.grade, uom: d.uom, cartons: 0, qtyPerCtn: 0, totalQty: d.qty, weightKg: d.weightKg, srcPage: d.srcPage, mtcIds: [], heatNo: '', lotNo: '', marking: '', unclear: [] }));
    }
    pl.forEach((l) => { l.mtcIds = autoLink(l, mtc); Object.assign(l, deriveHeatLot(l, mtc)); });

    const pageHeaders = results.filter((r) => r.docType && r.docType !== 'ERROR' && r.docType !== 'OTHER').map((r) => ({ page: r._page, docType: r.docType, invoiceNo: clean(r.invoiceNo), poNo: clean(r.poNo) }));
    return {
      header: { supplier: hdrOf('supplier').toUpperCase(), invoiceNo: hdrOf('invoiceNo'), dnNo: hdrOf('dnNo'), poNo: hdrOf('poNo'), project, receivedDate: stamp || todayISO },
      pl, dn, mtc, plFromDn, pageHeaders,
      docsSeen: { pl: of('PACKING_LIST').length > 0, dn: of('DELIVERY_NOTE').length > 0, mtc: of('MTC').length > 0 },
      readErrors: results.filter((r) => r.docType === 'ERROR').length,
      ack: {}
    };
  };

  // ---- verification ----
  const groupKey = (item, size) => productsOf(item + ' ' + size).join('+') + '|' + sizeKey(size || item);
  const norm = (rv) => ({ ...rv, pl: rv.pl.map((l) => ({ ...l, cartons: num(l.cartons), qtyPerCtn: num(l.qtyPerCtn), totalQty: num(l.totalQty), weightKg: num(l.weightKg) })), dn: rv.dn.map((d) => ({ ...d, qty: num(d.qty), weightKg: num(d.weightKg) })), mtc: rv.mtc.map((m) => ({ ...m, qty: num(m.qty) })) });
  const verify = (rv0) => {
    const rv = norm(rv0);
    const issues = [];
    const add = (severity, code, msg, ref, refId, page) => { if (issues.some((i) => i.code === code && i.msg === msg)) return; issues.push({ key: code + '|' + (refId || ref || ''), severity, code, msg, ref, refId, page }); };
    const { pl, dn, mtc, header } = rv;
    if (!rv.docsSeen.dn) add('warn', 'DOC_NO_DN', 'No delivery note page was recognised: quantities cannot be checked against a delivery note.', 'doc');
    if (!rv.docsSeen.pl) add('warn', 'DOC_NO_PL', 'No packing list page was recognised: pallet-wise details are taken from the delivery note and treated as one pallet. Please set pallet numbers.', 'doc');
    if (!rv.docsSeen.mtc || !mtc.length) add('error', 'DOC_NO_MTC', 'No test certificate (MTC) data was found: heat and lot numbers are missing for the whole delivery.', 'doc');
    if (!pl.length) add('error', 'NO_LINES', 'No material lines were found in the documents.', 'doc');
    if (rv.readErrors) add('warn', 'READ_ERR', `${rv.readErrors} page(s) could not be read by the AI. Check the page list and add the data manually if needed.`, 'doc');

    // header consistency across pages
    const invs = uniq(rv.pageHeaders.filter((h) => h.docType !== 'MTC').map((h) => alnum(h.invoiceNo)));
    if (invs.length > 1) add('error', 'INV_MISMATCH', 'Different invoice / delivery numbers appear on different pages: ' + uniq(rv.pageHeaders.map((h) => h.invoiceNo)).join(' vs ') + '. The pages may belong to different deliveries.', 'header');
    const pos = uniq(rv.pageHeaders.map((h) => alnum(h.poNo)));
    if (pos.length > 1) add('error', 'PO_MISMATCH', 'Different PO numbers appear across the documents: ' + uniq(rv.pageHeaders.map((h) => h.poNo)).join(' vs ') + '.', 'header');
    if (!clean(header.project)) add('error', 'NO_PROJECT', 'Project / PR number is missing (usually handwritten on the delivery note). Enter it in the header.', 'header');
    if (!clean(header.invoiceNo) && !clean(header.dnNo) && !clean(header.poNo)) add('error', 'NO_REF', 'No invoice, delivery note or PO number: a document reference is needed for the receipt.', 'header');

    // line checks
    pl.forEach((l) => {
      const nm = (l.item || 'Line') + (l.size ? ' ' + l.size : '');
      if (!clean(l.item)) add('error', 'LINE_NO_ITEM', 'A line has no item description.', 'pl', l.id, l.srcPage);
      if (!(l.totalQty > 0)) add('error', 'LINE_NO_QTY', `${nm}: quantity is missing or zero.`, 'pl', l.id, l.srcPage);
      if (l.palletGuessed && rv.docsSeen.pl) add('warn', 'PALLET_GUESS', `${nm}: no pallet number on the page, assumed pallet ${l.pallet}.`, 'pl', l.id, l.srcPage);
      if (l.cartons > 0 && l.qtyPerCtn > 0 && Math.round(l.cartons * l.qtyPerCtn) !== Math.round(l.totalQty)) add('warn', 'ARITH', `${nm}: ${l.cartons} ctn × ${l.qtyPerCtn} = ${l.cartons * l.qtyPerCtn}, but total quantity is ${l.totalQty}.`, 'pl', l.id, l.srcPage);
      if ((l.unclear || []).length) add('warn', 'UNCLEAR', `${nm}: the AI was unsure about ${l.unclear.join(', ')}. Please check against the page.`, 'pl', l.id, l.srcPage);
      const linked = (l.mtcIds || []).map((id) => mtc.find((m) => m.id === id)).filter(Boolean);
      const need = productsOf(l.item + ' ' + l.size);
      if (!linked.length) add('error', 'NO_MTC', `${nm}: no test certificate (MTC) is linked.`, 'pl', l.id, l.srcPage);
      else {
        need.forEach((t) => { if (!linked.some((m) => m.product === t)) add('error', 'NO_MTC_PART', `${nm}: no ${t.toLowerCase()} certificate linked (item is a ${need.join(' + ').toLowerCase()} set).`, 'pl', l.id, l.srcPage); });
        if (!clean(l.heatNo)) add('error', 'NO_HEAT', `${nm}: heat number is empty.`, 'pl', l.id, l.srcPage);
        if (!clean(l.lotNo)) add('error', 'NO_LOT', `${nm}: lot number is empty.`, 'pl', l.id, l.srcPage);
        // grade check per product
        const lg = gradeTokens(l.grade || l.item);
        linked.forEach((m) => {
          const mg = gradeTokens(m.grade + ' ' + m.marking);
          if (!lg.length || !mg.length) return;
          const relevant = lg.filter((g) => (m.product === 'BOLT' && /^A(325|490|307|193)/.test(g)) || (m.product === 'NUT' && /^A(563|194)/.test(g)) || (m.product === 'WASHER' && /^F(436|844)/.test(g)));
          if (relevant.length && !relevant.some((g) => mg.includes(g))) add('error', 'GRADE', `${nm}: grade ${relevant.join('/')} on the packing list, but the ${m.product.toLowerCase()} certificate (page ${m.srcPage}) shows ${mg.join('/')}.`, 'pl', l.id + ':' + m.id, m.srcPage);
        });
      }
      [l.heatNo, l.lotNo].forEach((v, i) => { if (clean(v) && /[^A-Za-z0-9,\-\/\s.]/.test(v)) add('warn', 'FORMAT', `${nm}: ${i ? 'lot' : 'heat'} number contains unusual characters (“${v}”). Check for a misread.`, 'pl', l.id + ':' + i, l.srcPage); });
    });

    // grouped quantity checks: PL vs DN, PL vs MTC
    const plG = {}; pl.forEach((l) => { const k = groupKey(l.item, l.size); (plG[k] = plG[k] || { name: l.item + ' ' + l.size, qty: 0, wt: 0, lines: [], page: l.srcPage }); plG[k].qty += l.totalQty; plG[k].wt += l.weightKg; plG[k].lines.push(l); });
    const dnG = {}; dn.forEach((d) => { const k = groupKey(d.item, d.size); (dnG[k] = dnG[k] || { name: d.item + ' ' + d.size, qty: 0, wt: 0, page: d.srcPage }); dnG[k].qty += d.qty; dnG[k].wt += d.weightKg; });
    if (rv.docsSeen.dn && rv.docsSeen.pl && !rv.plFromDn) {
      Object.keys(plG).forEach((k) => {
        const g = plG[k], d = dnG[k];
        if (!d) { add('error', 'NOT_ON_DN', `${g.name.trim()} is on the packing list (${g.qty}) but not on the delivery note.`, 'grp', k, g.page); return; }
        if (Math.round(g.qty) !== Math.round(d.qty)) add('error', 'QTY_PL_DN', `${g.name.trim()}: packing list ${g.qty} vs delivery note ${d.qty} (difference ${g.qty - d.qty}).`, 'grp', k, d.page);
        if (g.wt > 0 && d.wt > 0 && Math.abs(g.wt - d.wt) / Math.max(g.wt, d.wt) > 0.05) add('warn', 'WT_PL_DN', `${g.name.trim()}: weight ${round1(g.wt)} kg on the packing list vs ${round1(d.wt)} kg on the delivery note.`, 'grp', k, d.page);
      });
      Object.keys(dnG).forEach((k) => { if (!plG[k]) add('error', 'NOT_ON_PL', `${dnG[k].name.trim()} is on the delivery note (${dnG[k].qty}) but not on the packing list.`, 'grp', k, dnG[k].page); });
      const tp = pl.reduce((s, l) => s + l.weightKg, 0), td = dn.reduce((s, l) => s + l.weightKg, 0);
      if (tp > 0 && td > 0 && Math.abs(tp - td) / Math.max(tp, td) > 0.05) add('warn', 'WT_TOTAL', `Total weight: ${round1(tp)} kg on the packing list vs ${round1(td)} kg on the delivery note.`, 'doc', 'wt');
    }
    // PL vs MTC quantity (bolts / any product whose certificate lists a quantity)
    Object.keys(plG).forEach((k) => {
      const g = plG[k];
      const rows = uniq(g.lines.flatMap((l) => l.mtcIds || [])).map((id) => mtc.find((m) => m.id === id)).filter(Boolean);
      const withQty = rows.filter((m) => m.qty > 0);
      if (withQty.length) {
        const prod = withQty[0].product;
        const sum = withQty.filter((m) => m.product === prod).reduce((s, m) => s + m.qty, 0);
        if (Math.round(sum) !== Math.round(g.qty)) add('error', 'QTY_PL_MTC', `${g.name.trim()}: packing list ${g.qty} vs ${prod.toLowerCase()} certificate ${sum} (page ${withQty[0].srcPage}). Short / excess against the certificate.`, 'grp', k + ':mtc', withQty[0].srcPage);
      }
    });
    // MTC rows not used
    mtc.forEach((m) => { if (!pl.some((l) => (l.mtcIds || []).includes(m.id))) add('info', 'MTC_UNUSED', `Certificate row ${m.product.toLowerCase()} ${m.size} (heat ${m.heatNo || '—'}, page ${m.srcPage}) is not linked to any line.`, 'mtc', m.id, m.srcPage); });
    mtc.forEach((m) => { if (!clean(m.heatNo) || !clean(m.lotNo)) add('warn', 'MTC_INCOMPLETE', `Certificate row ${m.product.toLowerCase()} ${m.size} (page ${m.srcPage}) is missing a ${!clean(m.heatNo) ? 'heat' : 'lot'} number.`, 'mtc', m.id + ':inc', m.srcPage); });
    return issues;
  };
  const round1 = (n) => Math.round(n * 10) / 10;

  // ---- pallet ids and stock lines ----
  const refTail = (h) => { const a = alnum(h.invoiceNo || h.dnNo || h.poNo || ''); return a ? a.slice(-6) : 'R' + Date.now().toString(36).slice(-5).toUpperCase(); };
  const buildPalletLines = (rv0, existingPalletIds) => {
    const rv = norm(rv0);
    const used = new Set(existingPalletIds || []);
    const tail = refTail(rv.header);
    const palletNos = uniq(rv.pl.map((l) => clean(l.pallet) || '1'));
    const idFor = {};
    palletNos.forEach((pn) => {
      let id = `PLT-${tail}-${String(pn).replace(/[^A-Za-z0-9]/g, '').padStart(2, '0')}`, n = 2;
      while (used.has(id)) id = `PLT-${tail}-${String(pn).replace(/[^A-Za-z0-9]/g, '').padStart(2, '0')}-${n++}`;
      used.add(id); idFor[pn] = id;
    });
    // merge same item+size+heat+lot within a pallet
    const merged = {};
    rv.pl.forEach((l) => {
      const pn = clean(l.pallet) || '1';
      const k = [pn, alnum(l.item), alnum(l.size), alnum(l.heatNo), alnum(l.lotNo)].join('|');
      const m = merged[k] || (merged[k] = { pn, line: l, cartons: 0, qty: 0, wt: 0, parts: [], pages: new Set() });
      m.cartons += l.cartons; m.qty += l.totalQty; m.wt += l.weightKg; if (l.cartons && l.qtyPerCtn) m.parts.push(`${l.cartons}×${l.qtyPerCtn}`); m.pages.add(l.srcPage);
    });
    const mtcPagesFor = (l) => uniq((l.mtcIds || []).map((id) => (rv.mtc.find((m) => m.id === id) || {}).srcPage));
    return Object.values(merged).map((m) => {
      const l = m.line; const text = clean(l.item); const cut = text.search(/\s(FULL THREAD|HDG)\b/i);
      return {
        palletNo: m.pn, palletId: idFor[m.pn],
        sku: cut > 0 ? text.slice(0, cut).trim() : text, description: cut > 0 ? text.slice(cut).trim() : '', size: clean(l.size) || 'Standard Euro',
        cartons: Math.round(m.cartons) || 0, totalPcs: Math.round(m.qty) || 0, weightKg: round1(m.wt), uom: clean(l.uom) || 'PCS',
        breakdown: `Pallet ${m.pn}` + (m.parts.length ? ' · ' + m.parts.join(' + ') + ' pcs/ctn' : ''),
        grade: clean(l.grade), marking: clean(l.marking), heatNo: clean(l.heatNo), lotNo: clean(l.lotNo),
        srcPages: { pl: Array.from(m.pages).filter(Boolean), mtc: mtcPagesFor(l) }
      };
    });
  };
  return { norm, clean, num, alnum, uniq, nid, productsOf, sizeTokens, sizeKey, gradeOf, autoLink, deriveHeatLot, buildReview, verify, buildPalletLines, groupKey, round1 };
})();

// ===================== Original-document store (IndexedDB, falls back to memory) =====================
const DocStore = (() => {
  const mem = {};
  const open = () => new Promise((res, rej) => {
    try {
      const r = window.indexedDB.open('assent_wms_docs', 1);
      r.onupgradeneeded = () => { r.result.createObjectStore('docs', { keyPath: 'id' }); };
      r.onsuccess = () => res(r.result);
      r.onerror = () => rej(r.error);
    } catch (e) { rej(e); }
  });
  return {
    async put(id, files) {
      mem[id] = files;
      let cloudOk = false;
      if (typeof window !== 'undefined' && window.CloudDocs) {
        try { cloudOk = await window.CloudDocs.put(id, files); } catch (e) { console.warn('CloudDocs.put failed', e); }
      }
      try {
        const db = await open();
        await new Promise((res, rej) => { const tx = db.transaction('docs', 'readwrite'); tx.objectStore('docs').put({ id, files, saved: Date.now() }); tx.oncomplete = res; tx.onerror = () => rej(tx.error); });
        return true;
      } catch (e) { console.warn('DocStore.put failed', e); return cloudOk; }
    },
    async get(id) {
      if (mem[id]) return mem[id];
      if (typeof window !== 'undefined' && window.CloudDocs) {
        try { const f = await window.CloudDocs.get(id); if (f) { mem[id] = f; return f; } } catch (e) { console.warn('CloudDocs.get failed', e); }
      }
      try {
        const db = await open();
        return await new Promise((res, rej) => { const rq = db.transaction('docs').objectStore('docs').get(id); rq.onsuccess = () => res(rq.result ? rq.result.files : null); rq.onerror = () => rej(rq.error); });
      } catch (e) { return null; }
    }
  };
})();

// Printable pallet labels (HTML, one A5 label per pallet)
function buildPalletLabelsHtml(pallets) {
  const esc = (v) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const labels = pallets.map((p) => `
  <section class="label">
    <div class="brand">ASSENT STEEL INDUSTRIES · FASTENERS STORE</div>
    <div class="pid">${esc(p.palletId)}</div>
    <div class="meta"><b>Project:</b> ${esc(p.project)} &nbsp; <b>Supplier:</b> ${esc(p.supplier || '—')}</div>
    <div class="meta"><b>Invoice / DN:</b> ${esc(p.ref || '—')} &nbsp; <b>PO:</b> ${esc(p.poNo || '—')} &nbsp; <b>Received:</b> ${esc(p.date || '')}</div>
    ${p.locations && p.locations.length ? `<div class="meta"><b>Rack location:</b> ${esc(p.locations.join(', '))}</div>` : ''}
    <table><tr><th>Item</th><th>Size</th><th>Qty</th><th>Heat No</th><th>Lot No</th></tr>
    ${p.lines.map((l) => `<tr><td>${esc([l.sku, l.description].filter(Boolean).join(' '))}</td><td>${esc(l.size)}</td><td>${esc(l.totalPcs)} ${esc(l.uom || '')}</td><td>${esc(l.heatNo)}</td><td>${esc(l.lotNo)}</td></tr>`).join('')}
    </table>
  </section>`).join('');
  return `<!doctype html><html><head><meta charset="utf-8"><title>Pallet labels</title><style>
  @page { size: A5 landscape; margin: 8mm; }
  body { font-family: Arial, sans-serif; margin: 0; color: #111; }
  .label { page-break-after: always; border: 3px solid #1d3865; padding: 10px 14px; margin: 8px; }
  .brand { font-size: 11px; font-weight: 700; color: #1d3865; letter-spacing: 1px; }
  .pid { font-size: 44px; font-weight: 900; font-family: monospace; margin: 6px 0; }
  .meta { font-size: 13px; margin: 3px 0; }
  table { border-collapse: collapse; width: 100%; margin-top: 8px; font-size: 12px; }
  th, td { border: 1px solid #999; padding: 3px 5px; text-align: left; }
  th { background: #eef2f7; }
  .bar { position: fixed; top: 0; left: 0; right: 0; background: #1d3865; color: #fff; padding: 8px; font-size: 13px; }
  @media print { .bar { display: none; } }
  </style></head><body><div class="bar">Pallet labels: <button onclick="window.print()">Print</button></div><div style="height:40px"></div>${labels}</body></html>`;
}

