  useEffect(() => { try { localStorage.setItem(STORAGE_KEY_TXN, JSON.stringify(transactions)); } catch (e) {} }, [transactions]);
  useEffect(() => { try { localStorage.setItem(STORAGE_KEY_RECEIPTS, JSON.stringify(receipts)); } catch (e) {} }, [receipts]);
  const [toast, setToast] = useState(null);

  // Weekly Report Modal States
  const [reportModalOpen, setReportModalOpen] = useState(false);
  const [reportRangeType, setReportRangeType] = useState('DEFAULT_WEEK'); // 'DEFAULT_WEEK' or 'CUSTOM'
  
  // Pick any day; the report covers the full Monday-to-Sunday week before that day's week.
  const toISODate = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  const getLastWeekFor = (dayStr) => {
    const [y, m, d] = (dayStr || CURRENT_DATE_STR).split('-').map(Number);
    const dow = new Date(y, m - 1, d).getDay(); // 0 = Sunday
    const mon = new Date(y, m - 1, d + (dow === 0 ? -6 : 1 - dow) - 7);
    const sun = new Date(mon.getFullYear(), mon.getMonth(), mon.getDate() + 6);
    return { start: toISODate(mon), end: toISODate(sun) };
  };
  const fmtDay = (s) => { const [y, m, d] = s.split('-').map(Number); return new Date(y, m - 1, d).toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' }); };
  const [reportPickDay, setReportPickDay] = useState(CURRENT_DATE_STR);
  const { start: reportStartDate, end: reportEndDate } = getLastWeekFor(reportPickDay);

  // Search & Filter States
  const [outboundProjectSearch, setOutboundProjectSearch] = useState('');
