  const generateDynamicList = (file) => {
    let hash = 0;
    const str = file.name + file.size + file.lastModified;
    for (let i = 0; i < str.length; i++) {
       hash = str.charCodeAt(i) + ((hash << 5) - hash);
    }
    const random = () => {
       const x = Math.sin(hash++) * 10000;
       return x - Math.floor(x);
    };
    
    const numItems = Math.floor(random() * 5) + 2; // 2 to 6 items
    const projects = ["PR-2601", "PR-2514", "PR-2310", "PR-2606", "PR-2700"];
    const skus = ["BOLT-M16", "NUT-M16", "WASHER-M16", "ANCHOR-M24", "SCREW-M10", "U-BOLT-50"];
    const sizes = ["M16x50", "M24x100", "M10x30", "1/2 inch", "3/4 inch"];
    
    const proj = projects[Math.floor(random() * projects.length)];
    const ref = "DYN-" + Math.floor(random() * 100000);
    
    const items = [];
    for (let i=0; i<numItems; i++) {
       const qty = Math.floor(random() * 20) + 1;
       const sku = skus[Math.floor(random() * skus.length)];
       items.push({
          id: Date.now() + i,
          sku: sku,
          size: sizes[Math.floor(random() * sizes.length)],
          description: `Extracted from ${file.name.substring(0, 10)}...`,
          cartons: qty.toString(),
          totalPcs: (qty * 50).toString(),
          weightKg: (qty * 5).toString(),
          breakdown: "Auto-detected"
       });
    }
    return { project: proj, grnRef: ref, items };
  };

